INSERT INTO LMS_SCHEMA.LMS_TRNG_SUMMARY (TRNG_TOPIC, TRNG_DETAILS, PRE_REQUISITES, LEVEL_CODE, RATING, CATEGORY, TOOLS_NEEDED, TRNG_DURATION, FOLDER_PATH,TRAINER_EMAILS, CREATED_BY, CREATED_TS, UPDATED_BY, UPDATED_TS) VALUES ('Apache Flink','This course provides comprehensive training on Apache Flink for real-time and batch data processing. Students master DataSet and DataStream APIs, transformation operations, watermarks, late element handling, and deployment strategies. The 15.0-hour program covers essential concepts for building scalable streaming applications and processing large-scale data efficiently in distributed environments.','Basics of distributed systems and SQL','Advanced',4.5,'Big Data / Streaming','1. Hardware Requirements
For Each Participant (Local Machine or VM)
Minimum for basic local jobs and development:
●	CPU: Quad-core (4 cores)
●	RAM: 8 GB (16 GB recommended for smooth performance)
●	Disk: 20–30 GB free disk space
●	Network: Stable internet for package downloads and optional cluster setup
For Shared Cluster 
If a multi-node Flink cluster is demonstrated:
●	Master Node:
○	CPU: 4+ cores
○	RAM: 16–32 GB
○	Disk: SSD preferred
●	Worker Nodes:
○	CPU: 4+ cores each
○	RAM: 8–16 GB each
○	Network: LAN or cloud-based setup 
2. Software Requirements
Essential Software (All Machines)
Software	Version / Notes
Java JDK	Java 11 or Java 8 (compatible with Flink)
Apache Flink	Latest stable version (e.g., 1.18.x)
Scala	If using Scala API (2.12 recommended)
Python	If using PyFlink (Python 3.8–3.10)
Maven or Gradle	For building Java/Scala Flink jobs
Docker	For containerized setup (optional but useful)
Kafka (optional)	For streaming data ingestion demos
Git	For version control and sharing examples
IDE	IntelliJ IDEA / VS Code / Eclipse
Browser	Chrome / Firefox – for Flink Web UI access

Network & Access
●	Ports to open (locally or on VMs):
○	Flink JobManager Web UI: 8081
○	Kafka (if used): 9092
○	REST API endpoints: as per setup',15,'iElevate 4 Apache Flink','NA','SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP);
INSERT INTO LMS_SCHEMA.LMS_TRNG_SUMMARY (TRNG_TOPIC, TRNG_DETAILS, PRE_REQUISITES, LEVEL_CODE, RATING, CATEGORY, TOOLS_NEEDED, TRNG_DURATION, FOLDER_PATH,TRAINER_EMAILS, CREATED_BY, CREATED_TS, UPDATED_BY, UPDATED_TS) VALUES ('API Automation','This course provides specialized training in API testing and automation methodologies. Participants learn to work with REST and SOAP APIs, implement authentication mechanisms, handle serialization/deserialization, and utilize tools like Postman and Swagger. The comprehensive curriculum covers framework development, JSON manipulation, and best practices for creating robust API automation solutions.','Core Java (OOPs, collections)','Intermediate',4.67,'Quality Engineering','postman, intellid idea or eclipse , java (JDK)',12.5,'API Automation_Nov''23_SBU1_CDP','ankit.shah01@irissoftware.com, jitendra.khedar@irissoftware.com, ruchira.shukla@irissoftware.com','SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP);
